def pdf(file,label='Open PDF',prefix=R):
    return f'<a href="{prefix}{file}" target="_blank" rel="noopener">{label}</a>'
def ref(view,label):return f'<a href="Norse_Brainstorm.html#view-{view}" target="_blank" rel="noopener">{label}</a>'
def table(head,rows):return '<div class="tablewrap"><table><thead><tr>'+''.join(f'<th>{h}</th>' for h in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{v}</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def panel(title,body,cls=''):return f'<article class="card {cls}"><h3>{title}</h3>{body}</article>'
def section(id,title,intro,body):return f'<section id="{id}" class="view"><div class="sectionhead"><h2>{title}</h2><p>{intro}</p></div>{body}</section>'
def tag(t):return f'<span class="pill">{t}</span>'

