JS='''
const views=[...document.querySelectorAll('.view')];
function show(){let id=decodeURIComponent(location.hash.slice(1)||'overview');let target=document.getElementById(id);let view=target?.closest('.view')||document.getElementById('overview');views.forEach(v=>v.hidden=v!==view);document.querySelectorAll('nav a').forEach(a=>a.setAttribute('aria-current',a.hash==='#'+view.id?'page':'false'));if(target?.classList.contains('finding')){document.getElementById('audit-search').value='';document.getElementById('severity').value='';document.querySelectorAll('.finding').forEach(e=>e.hidden=false);}if(target?.tagName==='DETAILS')target.open=true;if(target&&target!==view)requestAnimationFrame(()=>target.scrollIntoView({block:'start'}));else window.scrollTo(0,0);}
window.addEventListener('hashchange',show);show();
const checks=[...document.querySelectorAll('[data-check]')],key='norse-review-20260922-props-tally-perches';let saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}')}catch(e){}checks.forEach(c=>{c.checked=!!saved[c.dataset.check];c.addEventListener('change',()=>{saved[c.dataset.check]=c.checked;try{localStorage.setItem(key,JSON.stringify(saved))}catch(e){}filterProps();});});
function filterProps(){let cat=document.getElementById('prop-filter').value,remaining=document.getElementById('remaining').checked;checks.forEach(c=>{let row=c.closest('tr');row.classList.toggle('done',c.checked);row.hidden=(cat&&!row.cells[0].innerText.includes(cat))||(remaining&&c.checked);});document.getElementById('checkcount').textContent=checks.filter(c=>c.checked).length+' / '+checks.length+' prepared';}
document.getElementById('prop-filter').addEventListener('change',filterProps);document.getElementById('remaining').addEventListener('change',filterProps);filterProps();
document.getElementById('export-checks').addEventListener('click',()=>{let body='Norse review prop checklist — 22 September 2026\\n\\n'+checks.map(c=>'['+(c.checked?'x':' ')+'] '+[...c.closest('tr').cells].slice(1).map(x=>x.innerText).join(' | ')).join('\\n');let url=URL.createObjectURL(new Blob([body],{type:'text/plain;charset=utf-8'}));let a=document.createElement('a');a.href=url;a.download='Norse_Review_Prop_Checklist.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),500);});
function filterIssues(){let q=document.getElementById('audit-search').value.toLowerCase(),s=document.getElementById('severity').value;document.querySelectorAll('.finding').forEach(e=>e.hidden=!(e.textContent.toLowerCase().includes(q)&&(!s||e.dataset.priority.includes(s))));}
document.getElementById('audit-search').addEventListener('input',filterIssues);document.getElementById('severity').addEventListener('change',filterIssues);
document.getElementById('trail-filter').addEventListener('change',e=>document.querySelectorAll('[data-trail]').forEach(c=>c.hidden=!!e.target.value&&c.dataset.trail!==e.target.value));
'''
